  1|﻿using System.Runtime.ConstrainedExecution;
  2|
  3|namespace CafeApp.Domain;
  4|
  5|public class Bill
  6|{
  7|    private Bill() { }
  8|    public int Id { get; private set; }
  9|
 10|
 11|    public int OrderId { get; private set; } //FK
 12|
 13|
 14|    public decimal TotalAmount => 
 15|        BaseAmount + Adjustments.Sum(x => x.Amount) - Payments.Sum(x => x.Amount);
 16|    public decimal BaseAmount { get; private set; }
 17|    public decimal PaidAmount { get; private set; }
 18|
 19|    public DateTime CreatedTime { get; private set; }
 20|    public DateTime? DeliveredTime { get; private set; }
 21|
 22|
 23|
 24|    public BillStatusEnum BillStatus { get; private set; }
 25|
 26|    private readonly List<BillAdjustment> _adjustments = new();
 27|    public IReadOnlyCollection<BillAdjustment> Adjustments
 28|        => _adjustments.AsReadOnly();
 29|
 30|    private readonly List<Payment> _payments = new(); 
 31|    public IReadOnlyCollection<Payment> Payments 
 32|        => _payments.AsReadOnly();
 33|
 34|    #region Factory Method
 35|    public static Bill Create(int orderId,decimal baseAmount)
 36|    {
 37|        if (baseAmount < 0)
 38|            throw new InvalidOperationException();
 39|
 40|        var bill = new Bill
 41|        {
 42|            OrderId = orderId,
 43|            BaseAmount = baseAmount,
 44|            CreatedTime = DateTime.UtcNow,
 45|            BillStatus = BillStatusEnum.Generated
 46|        };
 47|
 48|        bill.AddDomainEvent(
 49|            new BillGenerated(
 50|                bill.Id,
 51|                orderId,
 52|                baseAmount));
 53|
 54|        return bill;
 55|    }
 56|    #endregion
 57|
 58|    private readonly List<IDomainEvent> _domainEvents = new();
 59|    public IReadOnlyCollection<IDomainEvent> DomainEvents => _domainEvents;
 60|
 61|    #region Domain Events
 62|    private void AddDomainEvent(IDomainEvent domainEvent)
 63|    {
 64|        _domainEvents.Add(domainEvent);
 65|    }
 66|
 67|    public void ClearEvents()
 68|    {
 69|        _domainEvents.Clear();
 70|    }
 71|    #endregion
 72|
 73|    #region Commands (Behavior)
 74|    public void AddAdjustment(decimal amount,string reason)
 75|    {
 76|        EnsureNotClosed();
 77|        EnsureNotPaid();
 78|
 79|        var adjustment =
 80|            BillAdjustment.Create(
 81|                amount,
 82|                reason);
 83|
 84|        _adjustments.Add(adjustment);
 85|
 86|        if (TotalAmount < 0)
 87|            throw new InvalidOperationException(
 88|                "Bill cannot become negative.");
 89|
 90|        AddDomainEvent(
 91|            new BillAdjustmentAdded(
 92|                Id,
 93|                amount,
 94|                reason));
 95|    }
 96|    public void RegisterPayment(decimal amount)
 97|    {
 98|        EnsureNotClosed();
 99|
100|        if (amount <= 0)
101|            throw new InvalidOperationException();
102|
103|        if (PaidAmount + amount > TotalAmount)
104|            throw new InvalidOperationException(
105|                "Overpayment not allowed.");
106|
107|        PaidAmount += amount;
108|
109|        AddDomainEvent(
110|            new BillPaymentReceived(
111|                Id,
112|                amount));
113|
114|        if (PaidAmount == TotalAmount)
115|        {
116|            BillStatus = BillStatusEnum.Paid;
117|
118|            AddDomainEvent(
119|                new BillPaid(Id));
120|        }
121|        else
122|        {
123|            BillStatus = BillStatusEnum.PartiallyPaid;
124|        }
125|    }
126|    
127|    public void Close()
128|    {
129|        if (BillStatus != BillStatusEnum.Paid)
130|            throw new InvalidOperationException(
131|                "Only paid bills can be closed.");
132|
133|        BillStatus = BillStatusEnum.Closed;
134|
135|        DeliveredTime = DateTime.UtcNow;
136|
137|        AddDomainEvent(new BillClosed(Id));
138|    }
139|    #endregion
140|
141|    #region Invariants
142|
143|    private void EnsureNotClosed()
144|    {
145|        if (BillStatus == BillStatusEnum.Closed)
146|            throw new InvalidOperationException("Bill is already Closed.");
147|
148|    }
149|    private void EnsureNotPaid()
150|    {
151|        if (BillStatus == BillStatusEnum.Paid)
152|            throw new InvalidOperationException("Bill is already Paid.");
153|    }
154|
155|    #endregion
156|}
157|
158|//Invariants:
159|//   Cannot be paid twice
160|//   Total must equal sum of order snapshot
161|//   Adjustments cannot make total negative
162|//   Bill must be generated only once per order
163|
164|//Commands
165|//   GenerateBill
166|//   AddAdjustment
167|//   MarkAsPaid
168|
169|//State machine
170|//   Pending → Generated → Paid → Closed
171|
172|//Domain events
173|//   BillGenerated
174|//   BillAdjusted
175|//   PaymentReceived
176|
177|public record BillGenerated(int BillId,int OrderId,decimal Amount) 
178|    : IDomainEvent;
179|
180|public record BillAdjustmentAdded(int BillId,decimal Amount,string Reason) 
181|    : IDomainEvent;
182|
183|public record BillPaymentReceived(int BillId, decimal Amount) 
184|    : IDomainEvent;
185|
186|public record BillPaid(int BillId) : IDomainEvent;
187|
188|public record BillClosed(int BillId) : IDomainEvent;

