  1|﻿namespace CafeApp.Domain;
  2|
  3|public class Booking
  4|{
  5|    private Booking() { }
  6|    public int Id { get; private set; }
  7|
  8|
  9|    public int? TableId { get; private set; } //FK
 10|    public int CustomerId { get; private set; } //FK
 11|    
 12|
 13|    public BookingStatusEnum BookingState { get; private set; } 
 14|
 15|
 16|    public DateTime ReservationTime { get; private set; }
 17|    public int PeopleNumber { get; private set; }
 18|
 19|    #region Factory Method
 20|    public static Booking Create(int customerId,DateTime reservationTime,int peopleNumber)
 21|    {
 22|        if (peopleNumber <= 0)
 23|            throw new InvalidOperationException(
 24|                "Party size must be positive.");
 25|
 26|        if (reservationTime <= DateTime.UtcNow)
 27|            throw new InvalidOperationException(
 28|                "Reservation must be in future.");
 29|
 30|        var booking = new Booking
 31|        {
 32|            CustomerId = customerId,
 33|            ReservationTime = reservationTime,
 34|            PeopleNumber = peopleNumber,
 35|            BookingState = BookingStatusEnum.Pending
 36|        };
 37|
 38|        booking.AddDomainEvent(
 39|            new BookingCreated(
 40|                booking.Id,
 41|                customerId));
 42|
 43|        return booking;
 44|    }
 45|    #endregion
 46|
 47|    private readonly List<IDomainEvent> _domainEvents = new();
 48|    public IReadOnlyCollection<IDomainEvent> DomainEvents => _domainEvents;
 49|
 50|    #region Domain Events
 51|    private void AddDomainEvent(IDomainEvent domainEvent)
 52|    {
 53|        _domainEvents.Add(domainEvent);
 54|    }
 55|
 56|    public void ClearEvents()
 57|    {
 58|        _domainEvents.Clear();
 59|    }
 60|    #endregion
 61|
 62|    #region Commands (Behavior)
 63|    public void AssignTable(int tableId)
 64|    {
 65|        EnsureNotFinished();
 66|
 67|        TableId = tableId;
 68|
 69|        AddDomainEvent(
 70|            new TableAssignedToBooking(
 71|                Id,
 72|                tableId));
 73|    }
 74|
 75|
 76|    public void Confirm()
 77|    {
 78|        if (BookingState != BookingStatusEnum.Pending)
 79|            throw new InvalidOperationException(
 80|                "Only pending booking can be confirmed.");
 81|
 82|        BookingState = BookingStatusEnum.Confirmed;
 83|
 84|        AddDomainEvent(
 85|            new BookingConfirmed(Id));
 86|    }
 87|
 88|    public void Cancel(string reason)
 89|    {
 90|        if (BookingState == BookingStatusEnum.Completed)
 91|            throw new InvalidOperationException(
 92|                "Completed booking cannot be cancelled.");
 93|
 94|        if (BookingState == BookingStatusEnum.Cancelled)
 95|            return;
 96|
 97|        BookingState = BookingStatusEnum.Cancelled;
 98|
 99|        AddDomainEvent(
100|            new BookingCancelled(
101|                Id,
102|                reason));
103|    }
104|
105|    public void SeatCustomer()
106|    {
107|        if (BookingState != BookingStatusEnum.Confirmed)
108|            throw new InvalidOperationException(
109|                "Only confirmed booking can be seated.");
110|
111|        if (TableId == null)
112|            throw new InvalidOperationException(
113|                "Table must be assigned.");
114|
115|        BookingState = BookingStatusEnum.Seated;
116|
117|        AddDomainEvent(
118|            new CustomerSeated(Id));
119|    }
120|
121|    public void Complete()
122|    {
123|        if (BookingState != BookingStatusEnum.Seated)
124|            throw new InvalidOperationException(
125|                "Only seated booking can complete.");
126|
127|        BookingState = BookingStatusEnum.Completed;
128|
129|        AddDomainEvent(
130|            new BookingCompleted(Id));
131|    }
132|    #endregion
133|
134|    #region INVARIANTS
135|    private void EnsureNotFinished()
136|    {
137|        if (BookingState == BookingStatusEnum.Cancelled ||
138|            BookingState == BookingStatusEnum.Completed)
139|            throw new InvalidOperationException(
140|                "Cannot modify a finished booking.");
141|    }
142|    #endregion
143|}
144|//Invariants:
145|//   Cannot double-book same table/time slot
146|//   PeopleNumber must be > 0
147|//   Cannot confirm past reservation time
148|
149|//Commands
150|//   CreateBooking
151|//   ConfirmBooking
152|//   CancelBooking
153|
154|//State machine
155|//   Pending → Confirmed → Seated → Completed
156|//           ↘ Cancelled
157|
158|//Events
159|//   BookingCreated
160|//   BookingConfirmed
161|//   BookingCancelled
162|
163|public record BookingCreated(int BookingId,int CustomerId)
164|    : IDomainEvent;
165|
166|public record BookingConfirmed(int BookingId)
167|    : IDomainEvent;
168|
169|public record TableAssignedToBooking(int BookingId,int TableId)
170|    : IDomainEvent;
171|
172|public record BookingCancelled(int BookingId,string Reason)
173|    : IDomainEvent;
174|
175|public record CustomerSeated(int BookingId)
176|    : IDomainEvent;
177|
178|public record BookingCompleted(int BookingId)
179|    : IDomainEvent;

