  1|﻿using System.Xml.Linq;
  2|using System;
  3|
  4|namespace CafeApp.Domain;
  5|
  6|public class MenuItem
  7|{
  8|    private MenuItem() { }
  9|    public int Id { get; private set; }
 10|
 11|    public int MenuCategoryId { get; private set; } //FK
 12|
 13|
 14|    public string Name { get; private set; }
 15|    public decimal CurrentPrice { get; private set; }
 16|    
 17|    public MenuItemStatusEnum MenuItemStatus { get; private set; }
 18|
 19|
 20|    private readonly List<MenuItemModification> _allowedModifications = new();
 21|
 22|    public IReadOnlyCollection<MenuItemModification>
 23|        AllowedModifications => _allowedModifications.AsReadOnly();
 24|
 25|    #region Factory Method
 26|    public static MenuItem Create(
 27|        string name,
 28|        decimal price,
 29|        int categoryId)
 30|    {
 31|        if (string.IsNullOrWhiteSpace(name))
 32|            throw new InvalidOperationException();
 33|
 34|        if (price < 0)
 35|            throw new InvalidOperationException();
 36|
 37|        var item = new MenuItem
 38|        {
 39|            Name = name,
 40|            CurrentPrice = price,
 41|            MenuCategoryId = categoryId,
 42|            MenuItemStatus = MenuItemStatusEnum.Active
 43|        };
 44|
 45|        item.AddDomainEvent(
 46|            new MenuItemCreated(item.Id));
 47|
 48|        return item;
 49|    }
 50|    #endregion
 51|    #region Commands (Behavior)
 52|    public void ChangePrice(decimal newPrice)
 53|    {
 54|        if (newPrice < 0)
 55|            throw new InvalidOperationException();
 56|        if (CurrentPrice == newPrice)
 57|            return;
 58|
 59|        CurrentPrice = newPrice;
 60|
 61|        AddDomainEvent(
 62|            new MenuItemPriceChanged(Id,newPrice));
 63|    }
 64|    public void Deactivate()
 65|    {
 66|        MenuItemStatus = MenuItemStatusEnum.Inactive;
 67|
 68|        AddDomainEvent(new MenuItemDeactivated(Id));
 69|    }
 70|
 71|    public void Activate()
 72|    {
 73|        MenuItemStatus = MenuItemStatusEnum.Active;
 74|
 75|        AddDomainEvent(new MenuItemActivated(Id));
 76|    }
 77|    #endregion 
 78|    private readonly List<IDomainEvent> _domainEvents = new();
 79|    public IReadOnlyCollection<IDomainEvent> DomainEvents => _domainEvents;
 80|
 81|    #region Domain Events
 82|    private void AddDomainEvent(IDomainEvent domainEvent)
 83|    {
 84|        _domainEvents.Add(domainEvent);
 85|    }
 86|
 87|    public void ClearEvents()
 88|    {
 89|        _domainEvents.Clear();
 90|    }
 91|    #endregion
 92|}
 93|
 94|//Invariants
 95|//   Category name must be unique
 96|//   Archived category cannot contain active MenuItems
 97|//   Active MenuItem must belong to exactly one category
