  1|﻿using System.Diagnostics.Metrics;
  2|
  3|namespace CafeApp.Domain;
  4|
  5|public class Orders
  6|{
  7|    public int Id { get; private set; }
  8|
  9|
 10|    public int CreatedByStaffId { get; private set; } //FK
 11|    public int? TableSessionId { get; private set; } //FK
 12|
 13|
 14|    public DateTime CreatedTime { get; private set; }
 15|
 16|
 17|
 18|    private readonly List<OrderItem> _items = new();
 19|    public IReadOnlyCollection<OrderItem> OrderItems => _items.AsReadOnly();
 20|
 21|    private readonly List<IDomainEvent> _domainEvents = new();
 22|    public IReadOnlyCollection<IDomainEvent> DomainEvents => _domainEvents;
 23|
 24|
 25|    public OrderStatusEnum OrderStatus { get; private set; }
 26|    public OrderTypeEnum OrderType { get; private set; }
 27|
 28|    private Orders() { }
 29|
 30|    #region Factory Method
 31|    public static Orders Create(
 32|        int createdByStaffId, 
 33|        OrderTypeEnum type, 
 34|        int? tableSessionId = null)
 35|    {
 36|        var order = new Orders
 37|        {
 38|            Id = default, // TODO - like Guid.NewGuid(), DB auto generated
 39|            CreatedByStaffId = createdByStaffId,
 40|            TableSessionId = tableSessionId,
 41|            CreatedTime = DateTime.UtcNow,
 42|            OrderStatus = OrderStatusEnum.Draft,
 43|            OrderType = type
 44|        };
 45|
 46|        order.AddDomainEvent(new OrderCreated(order.Id, createdByStaffId));
 47|        return order;
 48|    }
 49|    #endregion 
 50|
 51|    #region Commands (Behavior)
 52|
 53|    public void AddItem(int menuItemId, int quantity, decimal unitPrice)
 54|    {
 55|        EnsureCanModify();
 56|
 57|        if (quantity <= 0)
 58|            throw new InvalidOperationException("Quantity must be greater than zero.");
 59|
 60|        var existing = _items.FirstOrDefault(x => x.MenuItemId == menuItemId);
 61|
 62|        if (existing != null)
 63|        {
 64|            existing.Increase(quantity);
 65|        }
 66|        else
 67|        {
 68|            _items.Add(OrderItem.Create(this.Id, menuItemId, quantity, unitPrice));
 69|        }
 70|
 71|        AddDomainEvent(new OrderItemAdded(Id, menuItemId, quantity));
 72|    }
 73|
 74|    public void RemoveItem(int menuItemId)
 75|    {
 76|        EnsureCanModify();
 77|
 78|        var item = _items.FirstOrDefault(x => x.MenuItemId == menuItemId);
 79|
 80|        if (item == null)
 81|            throw new InvalidOperationException("Item not found.");
 82|
 83|        _items.Remove(item);
 84|
 85|        AddDomainEvent(new OrderItemRemoved(Id, menuItemId));
 86|    }
 87|
 88|    public void Confirm()
 89|    {
 90|        EnsureCanModify();
 91|
 92|        if (!_items.Any())
 93|            throw new InvalidOperationException("Cannot confirm empty order.");
 94|
 95|        OrderStatus = OrderStatusEnum.Confirmed;
 96|
 97|        AddDomainEvent(new OrderConfirmed(Id));
 98|    }
 99|
100|    public void Cancel(string reason)
101|    {
102|        if (OrderStatus == OrderStatusEnum.Completed)
103|            throw new InvalidOperationException("Cannot cancel completed order.");
104|
105|        OrderStatus = OrderStatusEnum.Cancelled;
106|
107|        AddDomainEvent(new OrderCancelled(Id, reason));
108|    }
109|
110|    public void Complete()
111|    {
112|        if (OrderStatus != OrderStatusEnum.Confirmed)
113|            throw new InvalidOperationException("Only confirmed orders can be completed.");
114|
115|        OrderStatus = OrderStatusEnum.Completed;
116|
117|        AddDomainEvent(new OrderCompleted(Id));
118|    }
119|
120|    #endregion
121|
122|    #region Invariants
123|
124|    private void EnsureCanModify()
125|    {
126|        if (OrderStatus == OrderStatusEnum.Cancelled)
127|            throw new InvalidOperationException("Order is cancelled.");
128|
129|        if (OrderStatus == OrderStatusEnum.Completed)
130|            throw new InvalidOperationException("Order is completed.");
131|    }
132|
133|    #endregion
134|
135|
136|    #region Domain Events
137|
138|    private void AddDomainEvent(IDomainEvent domainEvent)
139|    {
140|        _domainEvents.Add(domainEvent);
141|    }
142|
143|    public void ClearEvents()
144|    {
145|        _domainEvents.Clear();
146|    }
147|
148|    #endregion
149|
150|
151|}
152|
153|#region Invariants-Aggrergate-Event-Handle
154|
155|//Invariants:
156|//   Cannot add items if order is Closed
157|//   Cannot change items after Paid
158|//   Order must have at least 1 item before confirmation
159|//   Total = sum(items + modifications)
160|
161|
162|//Commands
163|//   CreateOrder
164|//   AddItem
165|//   RemoveItem
166|//   ConfirmOrder
167|//   CancelOrder
168|
169|//State machine
170|//  Draft → Confirmed → Preparing → Served → Closed → Paid
171|//           ↘ Cancelled
